export const GUIDE_TOPICS={
 start:{title:'Bagaimana hendak bermula?',text:'Pilih nama dan avatar, kemudian buka lokasi pada peta atau senarai. Baca maklumat lokasi, semak laluan dan mulakan perjalanan. Cabaran dibuka selepas tiba.'},
 travel:{title:'Bagaimana masa perjalanan dikira?',text:'Masa permainan ialah anggaran masa pengangkutan dibahagi tiga. Contohnya 60 minit menjadi 20 minit. Menutup web tidak menghentikan pemasa. Gunakan Jeda untuk berhenti sementara; Batalkan mengembalikan penjelajah ke lokasi asal. Laluan bot belum tersedia.'},
 xp:{title:'Bagaimana hendak mengumpul XP?',text:'Misi selesai memberi 100 XP sekali bagi setiap lokasi. Setiap 10 minit masa permainan yang bergerak pula memberi 10 XP. Baki minit dibawa ke perjalanan seterusnya; masa dijeda, menunggu bas dan masa selepas tiba tidak dikira.'},
 challenge:{title:'Bagaimana jika jawapan belum tepat?',text:'Anda boleh cuba semula tanpa penalti. Gunakan Baca petunjuk lokasi untuk menyemak fakta; jawapan yang sedang diisi dikekalkan semasa beralih antara petunjuk dan cabaran. Misi selesai boleh dimainkan semula sebagai latihan tanpa tambahan XP atau cop.'},
 shop:{title:'Bagaimana hendak menggunakan Kedai?',text:'Semua pemain bermula berjalan kaki. XP boleh membuka bas jelajah, motor dan kereta sekali untuk digunakan berulang kali. Baki XP belanja berkurang, tetapi XP pencapaian dan cop kekal. Pengangkutan perjalanan yang sedang berlangsung tidak boleh ditukar. Bot menunggu laluan laut tersedia.'},
 collection:{title:'Di manakah kad dan lencana saya?',text:'Buka Pasport, kemudian Koleksi & lencana. Setiap misi selesai membuka satu kad penemuan. Lencana dikira daripada pencapaian seperti misi pertama, kategori lengkap dan semua 25 misi. Kemajuan lama turut diiktiraf tanpa bayaran XP. Selepas 25 misi lengkap, sijil pencapaian permainan boleh dimuat turun atau dicetak melalui Pasport.'},
 save:{title:'Bagaimana hendak menyimpan atau menukar peranti?',text:'Kemajuan disimpan pada pelayar dan peranti ini. Gunakan Eksport pasport sebelum memadam data pelayar atau menukar peranti. Di peranti baharu, gunakan Import pasport. Fail sandaran menyimpan profil, cop, inventori, rekod XP dan perjalanan yang sedang berlangsung.'}
};
export function guideAdvice(c){const name=c.name?`${c.name}, `:'';if(c.trip)return{kind:'journey',title:c.paused?'Perjalanan anda sedang dijeda':'Penjelajah sedang bergerak',message:`${name}destinasi anda ialah ${c.trip.name}. Baki ketika panduan dibuka: ${c.remaining}. ${c.paused?'Sambung apabila anda sedia.':'Anda boleh membaca maklumat dan menyemak pasport sementara menunggu.'}`,action:c.paused?'resume':'journey',label:c.paused?'Sambung perjalanan':'Lihat perjalanan',target:c.trip.id,topic:'travel'};if(!c.name)return{kind:'profile',title:'Salam, saya Jejak!',message:'Saya pemandu permainan anda. Pilih nama dan avatar dahulu, kemudian kita kenali warisan Labuan satu demi satu.',action:'profile',label:'Pilih penjelajah',topic:'start'};if(c.completed===25)return{kind:'complete',title:'Semua penemuan sudah dikumpul',message:`${name}anda telah melengkapkan 25 misi. Semak kad, lencana dan sijil pencapaian dalam Pasport, atau main semula misi sebagai latihan.`,action:'collection',label:'Lihat koleksi & lencana',topic:'collection'};if(c.here&&!c.currentDone)return{kind:'challenge',title:'Satu penemuan sedang menanti',message:`${name}anda sudah berada di ${c.current.name}. Baca fakta lokasi dan cuba cabarannya. Jawapan yang belum tepat boleh dicuba semula tanpa penalti.`,action:'challenge',label:`Buka cabaran ${c.current.id}`,target:c.current.id,topic:'challenge'};if(c.seaBlocked)return{kind:'sea',title:'Perjalanan laut memerlukan laluan bot',message:'Lokasi semasa anda di pulau. Data laluan dan jadual bot belum tersedia. Anda masih boleh membaca maklumat tapak dan mengulang misi yang sudah selesai sebagai latihan.',action:'map',label:'Lihat peta lokasi',topic:'travel'};if(c.onlyWalking&&c.balance>=150)return{kind:'shop',title:'XP anda boleh membuka pilihan baharu',message:`${name}baki belanja anda ialah ${c.balance} XP. Bas jelajah bermula pada 150 XP. Semak kadar perjalanan dan pilih pengangkutan mengikut gaya jelajah anda.`,action:'shop',label:'Semak Kedai XP',topic:'shop'};return{kind:'explore',title:'Mari teruskan jelajah',message:`${name}${c.next?`${c.next.name} boleh menjadi penemuan anda seterusnya.`:'Pilih satu lokasi pada peta untuk diterokai.'} Semak jarak dan anggaran masa sebelum bertolak.`,action:c.next?'site':'map',label:c.next?`Kenali ${c.next.id}`:'Lihat peta',target:c.next?.id,topic:'start'};}
